package com.skillswap.controller;
import com.skillswap.model.*; import com.skillswap.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/skills") public class SkillController {private final SkillRepository skills;private final UserRepository users;private final UserSkillRepository us; public SkillController(SkillRepository s,UserRepository u,UserSkillRepository x){skills=s;users=u;us=x;} @GetMapping public List<Skill> all(){return skills.findAll();} @GetMapping("/search") public List<Skill> search(@RequestParam String name){return skills.findByNameContainingIgnoreCase(name);} @PostMapping public Skill add(@RequestBody Skill s){return skills.save(s);} @PostMapping("/user/{userId}") public UserSkill addToUser(@PathVariable Long userId,@RequestBody Map<String,Object> x){UserSkill a=new UserSkill();a.setUser(users.findById(userId).orElseThrow());a.setSkill(skills.findById(Long.valueOf(x.get("skillId").toString())).orElseThrow());a.setType(UserSkill.SkillType.valueOf(x.get("type").toString()));return us.save(a);} @GetMapping("/user/{userId}") public List<UserSkill> userSkills(@PathVariable Long userId){return us.findByUserId(userId);} }
